<section class="page-head"><div class="container"><div class="eyebrow">PILOTAGE</div><h1>Administration</h1><p>Vision support, contenu et activité du portail.</p></div></section>
<section class="section"><div class="container"><div class="stat-grid admin-kpis"><?php foreach([['Utilisateurs',$kpis['users']],['Tickets non résolus',$kpis['open_tickets']],['Messages',$kpis['messages']],['Certifications',$kpis['certifications']]] as $k): ?><div class="stat-card"><strong><?= (int)$k[1] ?></strong><span><?= e($k[0]) ?></span></div><?php endforeach; ?></div><div class="panel"><div class="panel-head"><div><h2>Tickets récents</h2><p>Gestion des demandes d'assistance.</p></div></div><div class="admin-table"><div class="admin-tr admin-head"><span>Demande</span><span>Élève</span><span>Statut</span><span>Action</span></div><?php foreach($tickets as $t): ?><div class="admin-tr"><div><b>#<?= (int)$t['id'] ?> · <?= e($t['subject']) ?></b><small><?= e($t['message']) ?></small></div><span><?= e($t['user_name']) ?><small><?= e($t['email']) ?></small></span><span class="chip <?= $t['status']==='resolu'?'success':'neutral' ?>"><?= e(str_replace('_',' ',ucfirst($t['status']))) ?></span><form method="post" action="/admin/ticket"><input type="hidden" name="_csrf" value="<?= e($_SESSION['_csrf']) ?>"><input type="hidden" name="ticket_id" value="<?= (int)$t['id'] ?>"><select name="status" onchange="this.form.submit()"><option value="ouvert" <?= $t['status']==='ouvert'?'selected':'' ?>>Ouvert</option><option value="en_cours" <?= $t['status']==='en_cours'?'selected':'' ?>>En cours</option><option value="resolu" <?= $t['status']==='resolu'?'selected':'' ?>>Résolu</option></select></form></div><?php endforeach; ?></div></div></div></section>
